contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint creditAmount, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (creditAmount)); require(creditAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= creditAmount);
        uint bal0 = address(c).balance;

        c.deposit{value: creditAmount}(); if (__ESBMC_reverted()) return;
        uint bal1 = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint bal2 = address(c).balance;

        assert(
            (creditAmount > 0)
                ? (!reverted && bal1 - bal2 == creditAmount && bal2 == bal0)
                : (!reverted && bal2 == bal1)
        );
    }

    receive() external payable {}
}

