// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 creditAmount, uint256 withdrawAmount) internal {
        creditAmount = bound(creditAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= creditAmount);
        uint bal0 = address(c).balance;
        try c.deposit{value: creditAmount}() {} catch { return; }
        uint bal1 = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint bal2 = address(c).balance;
        assertTrue((creditAmount > 0)
                ? (!reverted && bal1 - bal2 == creditAmount && bal2 == bal0)
                : (!reverted && bal2 == bal1));
    }

    function testFuzz_run(uint256 creditAmount, uint256 withdrawAmount) public {
        _run(creditAmount, withdrawAmount);
    }

    receive() external payable {}
}
